def shift_outer_squares(N, grid):
    # Initialize the result grid with zeros
    result = [[0] * N for _ in range(N)]

    # Shift the outer squares clockwise by one square each
    for i in range(N):
        for j in range(N):
            if i == 0 or i == N-1 or j == 0 or j == N-1:
                result[i][j] = grid[i][j]
            else:
                result[i][j] = grid[(i-1)%N][(j-1)%N]

    return result

