def min_operations(N, A):
    min_val = min(A)
    max_val = max(A)
    operations = 0

    while max_val - min_val > 1:
        if max_val - min_val == 1:
            return 0
        if max_val - min_val == 2:
            operations += 1
            max_val -= 1
            min_val += 1
        else:
            operations += 1
            max_val -= 1
            min_val += 1

