def min_slimes(N, slimes):
    # Create a dictionary to store the count of each slime size
    slime_counts = {}
    for size, count in slimes:
        slime_counts[size] = count

    # Initialize the minimum number of slimes
    min_slimes = len(slime_counts)

    # Iterate through the slime counts
    for size, count in slime_counts.items():
